def parse_duration(s):
    if not s:
        return None

    parts = s.split()
    seconds = 0

    for part in parts:
        if 'h' in part:
            hours = int(part[:-1])
            seconds += hours * 3600
        elif 'm' in part:
            minutes = int(part[:-1])
            seconds += minutes * 60
        elif 's' in part:
            seconds += int(part)

    return seconds
```

