def title_case(s):
    if not s:
        return ""

    words = s.split()
    capitalized_words = [word.capitalize() for word in words]

    # Handle special cases
    if len(capitalized_words) > 0 and capitalized_words[0] == "a" or capitalized_words[0] == "e" or capitalized_words[0] == "i" or capitalized_words[0] == "o" or capitalized_words[0] == "u":
        capitalized_words[0] = capitalized_words[0].lower()

    return ' '.join(capitalized_words)
